window.enhancedTranslation = {
    init: function() {
        const initFn = () => {
            if (window.languageSwitcher) {
                this.extendTranslations();
                this.extendApplyLanguage();
                console.log("增强翻译功能已初始化");
            } else {
                console.error("语言切换器加载超时");
            }
        };

        if (window.languageSwitcher) {
            initFn();
        } else {
            const interval = setInterval(() => {
                if (window.languageSwitcher) {
                    clearInterval(interval);
                    initFn();
                }
            }, 200);
        }
    },

    extendTranslations: function() {
        window.languageSwitcher.translations = window.languageSwitcher.translations || {};
        window.languageSwitcher.translations.sections = {};
        window.languageSwitcher.translations.sections.titles = {
            "常用工具": {zh:"常用工具",en:"Common Tools"},
            "GS专区": {zh:"GS专区",en:"GS Zone"},
            "BGX专区":{zh:"BGX专区",en:"BGX Zone"},
            "天卡专区":{zh:"天卡专区",en:"Daily Card Zone"},
            "周卡专区":{zh:"周卡专区",en:"Weekly Card Zone"},
            "月卡专区":{zh:"月卡专区",en:"Monthly Card Zone"},
            "一体化区":{zh:"一体化区",en:"Integration Zone"},
            "云顶专区":{zh:"云顶专区",en:"TFT Zone"},
            "缓存专区":{zh:"缓存专区",en:"Cache Zone"},
            "特权专区":{zh:"特权专区",en:"Privilege Zone"},
            "过机器码专区":{zh:"过机器码专区",en:"Machine Code Zone"},
            "游戏资源": {zh:"游戏资源",en:"Game Resources"},
            "关于本站": {zh:"关于本站",en:"About Us"}
        };
        window.languageSwitcher.translations.common = {
            "密码":{zh:"密码",en:"Password"},
            "自带":{zh:"自带",en:"Built-in"},
            "支持":{zh:"支持",en:"Supports"},
            "数据库":{zh:"数据库",en:"Database"},
            "工具":{zh:"工具",en:"Tools"},
            "修复":{zh:"修复",en:"Fix"},
            "远程":{zh:"远程",en:"Remote"},
            "控制":{zh:"控制",en:"Control"},
            "软件":{zh:"软件",en:"Software"},
            "问题":{zh:"问题",en:"Issues"},
            "运行":{zh:"运行",en:"Run"},
            "组件":{zh:"组件",en:"Components"},
            "清理":{zh:"清理",en:"Clean"},
            "卡":{zh:"卡",en:"Card"},
            "专区":{zh:"专区",en:"Zone"},
            "一体":{zh:"一体",en:"All-in-one"},
            "特权":{zh:"特权",en:"Privilege"},
            "加速器":{zh:"加速器",en:"Accelerator"},
            "网吧":{zh:"网吧",en:"Internet Cafe"},
            "机器":{zh:"机器",en:"Machine"},
            "关于":{zh:"关于",en:"About"},
            "主站":{zh:"主站",en:"Home"},
            "更新时间":{zh:"更新时间",en:"Updated"},
            "刚刚更新":{zh:"刚刚更新",en:"Just updated"},
            "分钟前更新":{zh:"分钟前更新",en:" mins ago"},
            "小时前更新":{zh:"小时前更新",en:" hours ago"},
            "天前更新":{zh:"天前更新",en:" days ago"}
        };
    },

    extendApplyLanguage: function() {
        const originalApply = window.languageSwitcher.applyLanguage;
        window.languageSwitcher.applyLanguage = (lang) => {
            originalApply.call(window.languageSwitcher, lang);
            this.translatePage(lang);
        };
        
        // Listen for content changes (Nav Core generation)
        let isTranslating = false;
        const observer = new MutationObserver(() => {
            if (isTranslating) return;
            
            if (window.languageSwitcher.currentLanguage) {
                isTranslating = true;
                observer.disconnect();
                this.translatePage(window.languageSwitcher.currentLanguage);
                observeContent();
                isTranslating = false;
            }
        });
        
        const observeContent = () => {
            const contentContainer = document.getElementById('content-sections');
            if (contentContainer) observer.observe(contentContainer, { childList: true, subtree: true });
            const sidebarContainer = document.getElementById('main-menu');
            if (sidebarContainer) observer.observe(sidebarContainer, { childList: true, subtree: true });
        };
        
        observeContent();

        // Apply immediately if already loaded
        if (window.languageSwitcher.currentLanguage) {
            this.translatePage(window.languageSwitcher.currentLanguage);
        }
    },

    translatePage: function(lang) {
        this.translateSectionTitles(lang);
        this.translateItems(lang);
    },

    getOriginalText: function(el) {
        if (!el.getAttribute('data-original-text')) {
            const text = el.textContent.trim();
            if (text) {
                el.setAttribute('data-original-text', text);
            }
        }
        return el.getAttribute('data-original-text') || el.textContent.trim();
    },

    translateSectionTitles: function(lang) {
        // Sidebar titles
        document.querySelectorAll('.sidebar-menu .main-menu a .title, .sidebar-menu .main-menu a span').forEach(el => {
            // Only target elements that contain text and are likely titles
            if (el.tagName === 'SPAN' && el.classList.contains('tooltip-blue')) return; // Skip tooltips if needed, but titles are usually in span.title
            
            const original = this.getOriginalText(el);
            const map = window.languageSwitcher.translations.sections.titles;
            if (map[original] && map[original][lang]) {
                el.textContent = map[original][lang];
            }
        });
        
        // Content headers
        document.querySelectorAll('#content-sections h4').forEach(el => {
             el.childNodes.forEach(node => {
                 if (node.nodeType === 3 && node.textContent.trim()) {
                     const text = node.textContent.trim();
                     let key = null;
                     const titles = window.languageSwitcher.translations.sections.titles;
                     
                     // Try to match text to a key (ZH or EN)
                     for (let k in titles) {
                         if (titles[k].zh === text || titles[k].en === text) {
                             key = k;
                             break;
                         }
                     }
                     
                     if (key && titles[key][lang]) {
                         node.textContent = " " + titles[key][lang];
                     }
                 }
             });
        });
    },

    translateItems: function(lang) {
        const common = window.languageSwitcher.translations.common;
        
        // Translate Card Titles and Descriptions
        document.querySelectorAll('.xe-user-name strong, .xe-comment p').forEach(el => {
            const original = this.getOriginalText(el);
            
            if (lang === 'zh') {
                el.textContent = original;
            } else {
                let newText = original;
                // Sort keys by length desc to avoid partial replacement issues (e.g. "Card" vs "Weekly Card")
                const keys = Object.keys(common).sort((a,b) => b.length - a.length);
                for (let key of keys) {
                    if (newText.includes(key)) {
                        newText = newText.split(key).join(" " + common[key].en + " "); // Add spaces for EN
                    }
                }
                // Clean up double spaces
                el.textContent = newText.replace(/\s+/g, ' ').trim();
            }
        });
    }
};

window.enhancedTranslation.init();